+    $('#wheelOptions').innerHTML=wheels.map((w,i)=>`<button class="wheel-opt" data-wheel="${i}"><span class="wheel-icon">${w.icon}</span><b>${w.name}</b><small></small></button>`).join('');
+    $('#swatches').addEventListener('click',e=>{const b=e.target.closest('[data-color]');if(!b)return;save.color=+b.dataset.color;updateCar()});
+    $('#wheelOptions').addEventListener('click',e=>{const b=e.target.closest('[data-wheel]');if(!b)return;const i=+b.dataset.wheel;if(save.owned.includes(i)){save.wheel=i;updateCar();return}if(save.cash<wheels[i].price){announce(`You need $${wheels[i].price-save.cash} more for ${wheels[i].name} wheels.`);return}save.cash-=wheels[i].price;save.owned.push(i);save.wheel=i;updateCar();announce(`${wheels[i].name} wheels installed!`)});
