  const stage=$('.stage');stage.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;dragStart={x:e.clientX,rot:rotation};stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(dragStart){rotation=dragStart.rot+(e.clientX-dragStart.x)*.5;$('#carWrap').style.transform=`perspective(700px) rotateY(${rotation}deg) scale(${scale})`}});stage.addEventListener('pointerup',()=>dragStart=null);stage.addEventListener('pointercancel',()=>dragStart=null);stage.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.82,Math.min(1.16,scale-e.deltaY*.0005));$('#carWrap').style.transform=`perspective(700px) rotateY(${rotation}deg) scale(${scale})`},{passive:false});
}
function fitCanvas(canvas){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);const w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}const c=canvas.getContext('2d');c.setTransform(d,0,0,d,0,0);return {ctx:c,w:r.width,h:r.height};}
function segmentAt(i){return pieces.find(p=>p.kind===save.segments[i%save.segments.length]?.kind)||pieces[0]}
function trackCurve(t){const idx=Math.floor(((t%1)+1)%1*save.segments.length),seg=segmentAt(idx);return seg.curve||0}
function drawTrackPreview(){const canvas=$('#trackPreview');if(!canvas)return;const {ctx,w,h}=fitCanvas(canvas);ctx.clearRect(0,0,w,h);ctx.fillStyle='#28332e';ctx.fillRect(0,0,w,h);
  for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#ffffff08':'#00000008';ctx.fillRect(0,i*h/8,w,h/8)}
  const cx=w*.5,cy=h*.54,rx=Math.min(w*.34,92),ry=h*.35;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.strokeStyle='#151817';ctx.lineWidth=28;ctx.stroke();ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.strokeStyle='#d9ded3';ctx.lineWidth=2;ctx.setLineDash([9,9]);ctx.stroke();ctx.setLineDash([]);
  ctx.beginPath();ctx.ellipse(cx,cy,rx+15,ry+15,0,Math.PI*1.35,Math.PI*1.65);ctx.strokeStyle='#d8ff52';ctx.lineWidth=4;ctx.stroke();for(let i=0;i<4;i++){const a=i*Math.PI/2+.2;const x=cx+Math.cos(a)*rx,y=cy+Math.sin(a)*ry;ctx.fillStyle=i===0?'#d8ff52':'#aeb4ac';ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill()}
}
function drawBuilder(){const canvas=$('#builderCanvas');if(!canvas)return;const {ctx,w,h}=fitCanvas(canvas);ctx.clearRect(0,0,w,h);ctx.fillStyle='#18201e';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff0b';ctx.lineWidth=1;for(let x=0;x<w;x+=28){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
  const cx=w/2,cy=h/2+6,rx=Math.min(w*.32,180),ry=Math.min(h*.33,116);ctx.save();ctx.translate(cx,cy);ctx.beginPath();ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2);ctx.strokeStyle='#343b36';ctx.lineWidth=58;ctx.stroke();ctx.beginPath();ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2);ctx.strokeStyle='#c4cec4';ctx.lineWidth=2;ctx.setLineDash([11,9]);ctx.stroke();ctx.setLineDash([]);
  const n=Math.max(save.segments.length,4);for(let i=0;i<n;i++){const a=i/n*Math.PI*2-Math.PI/2,x=Math.cos(a)*rx,y=Math.sin(a)*ry;const kind=save.segments[i]?.kind||'straight';ctx.fillStyle=kind==='jump'?'#ff744e':kind==='corner'?'#71e3d2':kind==='chicane'?'#e4b7ff':'#d8ff52';ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();if(i===0){ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-7,-ry-25);ctx.lineTo(7,-ry-25);ctx.stroke()}}
  ctx.restore();ctx.fillStyle='#d8ff52';ctx.font='800 10px system-ui';ctx.textAlign='center';ctx.fillText('START / FINISH',cx,cy-ry-32);drawSegmentList();
}
function drawSegmentList(){const list=$('#segmentList');if(!list)return;$('#segmentCount').textContent=save.segments.length;const difficulty=save.segments.length<4?'—':save.segments.length<7?'EASY':save.segments.length<11?'MED':'HARD';$('#difficulty').textContent=difficulty;list.innerHTML=save.segments.length?save.segments.map((s,i)=>{const p=pieces.find(x=>x.kind===s.kind)||pieces[0];return `<div class="segment"><span><b style="color:var(--lime)">${String(i+1).padStart(2,'0')}</b> &nbsp;${p.icon} &nbsp;${p.name}</span><button class="remove-seg" aria-label="Remove ${p.name}" data-remove="${i}">×</button></div>`}).join(''):'<div class="section-sub">No sections yet. Add a piece to start building.</div>';$('#segmentList').onclick=e=>{const b=e.target.closest('[data-remove]');if(!b)return;save.segments.splice(+b.dataset.remove,1);persist();drawBuilder();drawTrackPreview()};
}
function setupBuilder(){
  $('#pieceTools').innerHTML=pieces.map(p=>`<button class="piece" data-piece="${p.kind}"><span>${p.icon}</span><b>${p.name}</b><small>${p.desc}</small></button>`).join('');$('#pieceTools').addEventListener('click',e=>{const b=e.target.closest('[data-piece]');if(!b)return;save.segments.push({kind:b.dataset.piece,id:Date.now()});persist();drawBuilder();drawTrackPreview();announce(`${pieces.find(p=>p.kind===b.dataset.piece).name} added.`)});
  $('#clearTrack').addEventListener('click',()=>{save.segments=[];persist();drawBuilder();drawTrackPreview()});$('#useTrack').addEventListener('click',()=>{if(save.segments.length<4){announce('Add at least 4 track sections before racing.');return}$('#trackName').textContent='CUSTOM CIRCUIT';$('#trackLaps').textContent='3 LAPS · 4 RACERS';showPage('customize');announce('Custom circuit selected. The grid is yours.')});drawBuilder();
}
function showPage(name){$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('.tab').forEach(t=>{const yes=t.dataset.page===name;t.classList.toggle('active',yes);t.setAttribute('aria-selected',String(yes))});if(name==='builder')requestAnimationFrame(drawBuilder);if(name==='customize')requestAnimationFrame(drawTrackPreview)}
$$('.tab').forEach(t=>t.addEventListener('click',()=>showPage(t.dataset.page)));

